package rpc

import (
	"fmt"
	"strings"
)

// File is a generated file, by its path under the output folder.
type File struct {
	Path    string
	Content []byte
}

// FilePath is where a package's .proto file goes: its dots as folders, and
// its last segment that isn't a version as the file's name.
func FilePath(pkg string) string {
	segs := strings.Split(pkg, ".")
	name := segs[len(segs)-1]
	for i := len(segs) - 1; i >= 0; i-- {
		if !isVersion(segs[i]) {
			name = segs[i]
			break
		}
	}
	return strings.Join(segs, "/") + "/" + name + ".proto"
}

// isVersion reports whether a package segment is a version, as v1 or
// v1beta2.
func isVersion(s string) bool {
	if len(s) < 2 || s[0] != 'v' || s[1] < '0' || s[1] > '9' {
		return false
	}
	return true
}

// BufYAML lints the generated files with buf's STANDARD rules, the
// package's version suffix left to its author.
const BufYAML = `# Generated by heron generate proto.
version: v2
lint:
  use:
    - STANDARD
  except:
    - PACKAGE_VERSION_SUFFIX
breaking:
  use:
    - FILE
`

// ProtoFiles writes each protobuf package as one .proto file, beside a
// buf.yaml.
func (m *Model) ProtoFiles() []File {
	var out []File
	for _, p := range m.Sorted() {
		out = append(out, File{Path: FilePath(p.Name), Content: []byte(p.Proto())})
	}
	if len(out) > 0 {
		out = append(out, File{Path: "buf.yaml", Content: []byte(BufYAML)})
	}
	return out
}

// Proto writes the package's .proto file.
func (p *Package) Proto() string {
	var b strings.Builder
	b.WriteString("// Generated by heron generate proto. DO NOT EDIT.\n")
	b.WriteString("syntax = \"proto3\";\n\n")
	fmt.Fprintf(&b, "package %s;\n", p.Name)
	if imps := p.Imports(); len(imps) > 0 {
		b.WriteString("\n")
		for _, i := range imps {
			fmt.Fprintf(&b, "import %q;\n", i)
		}
	}
	for _, s := range p.Services {
		b.WriteString("\n")
		comment(&b, "", ProseText(s.API))
		fmt.Fprintf(&b, "service %s {\n", s.Name)
		for i, me := range s.Methods {
			if i > 0 {
				b.WriteString("\n")
			}
			comment(&b, "  ", ProseText(me.Op))
			b.WriteString("  " + me.Signature())
			if me.Idempotency != "" {
				fmt.Fprintf(&b, " {\n    option idempotency_level = %s;\n  }\n", me.Idempotency)
			} else {
				b.WriteString(";\n")
			}
		}
		b.WriteString("}\n")
	}
	// The methods' messages in method order, then the types they reach in
	// the order they're reached.
	var ordered []*Message
	for _, s := range p.Services {
		for _, me := range s.Methods {
			ordered = append(ordered, me.Request, me.Response)
		}
	}
	for _, msg := range p.Messages {
		if msg.Method == nil {
			ordered = append(ordered, msg)
		}
	}
	for _, msg := range ordered {
		b.WriteString("\n")
		b.WriteString(msg.Proto())
	}
	for _, e := range p.Enums {
		b.WriteString("\n")
		b.WriteString(e.Proto())
	}
	return b.String()
}

// Signature is the method as the .proto writes it, as
// rpc Watch(WatchRequest) returns (stream WatchResponse).
func (me *Method) Signature() string {
	in, out := me.Request.Name, me.Response.Name
	if me.Kind == ClientStreaming || me.Kind == BidiStreaming {
		in = "stream " + in
	}
	if me.Kind == ServerStreaming || me.Kind == BidiStreaming {
		out = "stream " + out
	}
	return fmt.Sprintf("rpc %s(%s) returns (%s)", me.Name, in, out)
}

// Proto writes the message as the .proto file does.
func (msg *Message) Proto() string {
	var b strings.Builder
	comment(&b, "", msg.Doc)
	fmt.Fprintf(&b, "message %s {\n", msg.Name)
	if len(msg.Reserved) > 0 {
		var rs []string
		for _, r := range msg.Reserved {
			rs = append(rs, fmt.Sprint(r))
		}
		fmt.Fprintf(&b, "  reserved %s;\n", strings.Join(rs, ", "))
	}
	indent := "  "
	if msg.Oneof != "" {
		fmt.Fprintf(&b, "  oneof %s {\n", msg.Oneof)
		indent = "    "
	}
	for _, f := range msg.Fields {
		comment(&b, indent, f.Doc)
		b.WriteString(indent)
		if f.Label != "" {
			b.WriteString(f.Label + " ")
		}
		fmt.Fprintf(&b, "%s %s = %d;\n", f.Type, f.Name, f.Number)
	}
	if msg.Oneof != "" {
		b.WriteString("  }\n")
	}
	b.WriteString("}\n")
	return b.String()
}

// Proto writes the enum as the .proto file does.
func (e *Enum) Proto() string {
	var b strings.Builder
	comment(&b, "", e.Doc)
	fmt.Fprintf(&b, "enum %s {\n", e.Name)
	for _, v := range e.Values {
		comment(&b, "  ", v.Doc)
		fmt.Fprintf(&b, "  %s = %d;\n", v.Name, v.Number)
	}
	b.WriteString("}\n")
	return b.String()
}

func comment(b *strings.Builder, indent, doc string) {
	if doc == "" {
		return
	}
	for _, l := range wrap(doc, 76-len(indent)) {
		fmt.Fprintf(b, "%s// %s\n", indent, l)
	}
}

func wrap(s string, width int) []string {
	var out []string
	line := ""
	for _, w := range strings.Fields(s) {
		if line != "" && len(line)+1+len(w) > width {
			out = append(out, line)
			line = w
			continue
		}
		if line != "" {
			line += " "
		}
		line += w
	}
	if line != "" {
		out = append(out, line)
	}
	return out
}
